NEW = {'phone/server.py': '"""\nСервер Atlas для телефона и других устройств.\n\n    GET  /                    — приложение (страница; без ключа ничего не умеет)\n    GET  /manifest.webmanifest, /sw.js, /icon-*.png — чтобы телефон мог его «установить»\n    POST /api/pair            — проверить ключ сопряжения\n    POST /api/ask   {text}    — текстом      → {text, audio, mime}\n    POST /api/talk  (аудио)   — голосом      → {heard, text, audio, mime}\n\nВсе /api/*, кроме pair, требуют ключ сопряжения (заголовок X-Atlas-Key). Ключ знает только\nтелефон, который отсканировал QR-код. Страница с QR-кодом по сети не отдаётся вообще — она\nоткрывается файлом на самом компьютере.\n"""\nimport base64\nimport json\nimport os\nimport re\nimport secrets\nimport socketserver\nimport tempfile\nimport threading\nimport time\nfrom wsgiref.simple_server import WSGIRequestHandler, WSGIServer, make_server\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nSTATIC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static")\nPAIR_FILE = os.path.join(ROOT, "phone_pairing.json")\nPORT = int(os.getenv("PHONE_PORT") or 8765)\nMAX_AUDIO = 8 * 1024 * 1024                       # 8 МБ — больше минуты речи не бывает\n\n_state = {"server": None, "thread": None, "port": PORT, "url": None, "kind": None, "hint": ""}\n_brain_lock = threading.Lock()                    # телефон и компьютер не думают одновременно\n\n\n# =============================================================================\n# Сопряжение\n# =============================================================================\ndef _load_pair() -> dict:\n    try:\n        with open(PAIR_FILE, encoding="utf-8") as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\n\ndef pairing_token(create: bool = False) -> str:\n    """Секретный ключ: создаётся один раз и хранится в phone_pairing.json (в git не попадает)."""\n    data = _load_pair()\n    if not data.get("token") and create:\n        data = {"token": secrets.token_urlsafe(24), "created": time.time()}\n        with open(PAIR_FILE, "w", encoding="utf-8") as f:\n            json.dump(data, f)\n    return data.get("token", "")\n\n\ndef is_paired() -> bool:\n    return bool(_load_pair().get("token"))\n\n\nclass HTTPError(Exception):\n    def __init__(self, status: int, message: str):\n        super().__init__(message)\n        self.status, self.message = status, message\n\n\ndef _check_key(environ) -> None:\n    token = pairing_token()\n    got = environ.get("HTTP_X_ATLAS_KEY") or ""\n    if not token or not got or not secrets.compare_digest(got, token):\n        raise HTTPError(401, "Нужен ключ сопряжения: скажи Атласу на компьютере «установи себя на телефон».")\n\n\n# =============================================================================\n# Мозг: тот же путь, что голосом на компьютере, но ответ уходит в телефон\n# =============================================================================\ndef _emo():\n    try:\n        from core import emotions\n        return emotions\n    except Exception:\n        return None\n\n\nPHONE_QUIET = 30          # столько секунд после фразы с телефона компьютер не реагирует на «Атлас»\nPHONE_HINT = ("(Said on the phone: reply in 1-2 short spoken sentences; do only what was asked; apps, music and files "\n              "open on the computer — say so if it matters.) ")\n\n\ndef _hint(text: str) -> str:\n    """Язык ответа — как сказал человек (кириллица → русский), иначе как в настройках Atlas."""\n    if re.search(r"[а-яё]", text, re.I):\n        lang = "ru"\n    else:\n        try:\n            from voice import get_response_language\n            lang = get_response_language()\n        except Exception:\n            lang = "ru"\n    return ("(Respond in Russian.) " if lang == "ru" else "(Respond in English.) ") + PHONE_HINT\n\n\ndef _quiet_pc() -> None:\n    try:\n        from ui_state import shared_state\n        shared_state["phone_active_until"] = time.time() + PHONE_QUIET\n    except Exception:\n        pass\n\n\ndef handle_text(text: str) -> str:\n    """Быстрый путь → мозг. Компьютер при этом молчит: отвечает телефон."""\n    text = (text or "").strip()\n    if not text:\n        return ""\n    _quiet_pc()\n    with _brain_lock:\n        reply = None\n        try:\n            from fast_commands import try_fast_command\n            fast = try_fast_command(text)\n            if fast is not None:\n                reply = fast[1] if isinstance(fast, tuple) else str(fast)\n                try:\n                    from ai_brain import remember_exchange\n                    remember_exchange(text, reply)\n                except Exception:\n                    pass\n        except Exception as e:\n            print(f"[телефон] быстрый путь: {e}")\n        if reply is None:\n            from ai_brain import ask_ai\n            reply = ask_ai(_hint(text) + text)\n    em = _emo()\n    shown = em.strip(reply) if em else reply\n    print(f"[телефон] ← {shown}")\n    _quiet_pc()                                         # отсчёт тишины — с конца ответа\n    try:\n        from ui_state import shared_state                  # разговор виден и в окне на компьютере\n        shared_state.setdefault("chat_history", []).append(("You 📱", text))\n        shared_state["chat_history"].append(("Atlas", shown))\n    except Exception:\n        pass\n    try:\n        from core import memory\n        memory.log_turn("user", text)\n        memory.log_turn("assistant", shown)\n    except Exception:\n        pass\n    return reply\n\n\ndef synthesize(text: str):\n    """Голос Atlas файлом для телефона → (base64, mime) или (None, None) — тогда телефон скажет сам."""\n    if not text:\n        return None, None\n    try:\n        import voice\n        fn = os.path.join(tempfile.mkdtemp(prefix="atlas_phone_"), "reply.mp3")\n        real = voice._generate_any(text, fn)\n        with open(real, "rb") as f:\n            data = f.read()\n        mime = "audio/wav" if real.lower().endswith(".wav") else "audio/mpeg"\n        try:\n            os.remove(real)\n        except OSError:\n            pass\n        return base64.b64encode(data).decode("ascii"), mime\n    except Exception as e:\n        print(f"[телефон] голос не получился ({e}) — телефон скажет своим голосом")\n        return None, None\n\n\n_EXT = {"webm": "webm", "ogg": "ogg", "mp4": "m4a", "m4a": "m4a", "aac": "m4a", "mpeg": "mp3", "wav": "wav",\n        "x-wav": "wav"}\n\n\ndef transcribe(data: bytes, mime: str) -> str:\n    """Распознавание речи с телефона: тот же Whisper в Groq, те же настройки языка, что на компьютере."""\n    import voice\n    sub = (mime or "").split(";")[0].split("/")[-1].lower()\n    ext = _EXT.get(sub, "webm")\n    kw = dict(file=(f"phone.{ext}", data), model=getattr(voice, "STT_WHISPER", "whisper-large-v3"), temperature=0.0)\n    try:\n        lang = voice._stt_language()\n        if lang:\n            kw["language"] = lang\n        kw["prompt"] = voice._stt_prompt()\n    except Exception:\n        pass\n    r = voice.groq_client.audio.transcriptions.create(**kw)\n    text = (getattr(r, "text", "") or "").strip()\n    junk = getattr(voice, "_WHISPER_JUNK", set())\n    if not re.search(r"[^\\W_]", text) or re.sub(r"[^\\w\\s]", "", text.lower()).strip() in junk:\n        return ""\n    return text\n\n\ndef _answer(text: str, heard: str = None) -> dict:\n    reply = handle_text(text)\n    audio, mime = synthesize(reply)\n    em = _emo()\n    out = {"text": em.strip(reply) if em else reply, "audio": audio, "mime": mime}\n    if heard is not None:\n        out["heard"] = heard\n    return out\n\n\n# =============================================================================\n# Маршруты (стандартный WSGI — без сторонних библиотек)\n# =============================================================================\n_TYPES = {".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".png": "image/png"}\n\n\ndef _manifest() -> bytes:\n    return json.dumps({\n        "name": "Atlas", "short_name": "Atlas", "start_url": "/", "scope": "/", "display": "standalone",\n        "background_color": "#050814", "theme_color": "#050814", "orientation": "portrait",\n        "description": "Голосовой ассистент Atlas — с компьютера на телефон",\n        "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},\n                  {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"}],\n    }, ensure_ascii=False).encode("utf-8")\n\n\ndef _static(name: str):\n    path = os.path.join(STATIC, name)\n    if not os.path.isfile(path):\n        raise HTTPError(404, "Нет такой страницы.")\n    with open(path, "rb") as f:\n        data = f.read()\n    headers = [("Content-Type", _TYPES.get(os.path.splitext(name)[1], "application/octet-stream")),\n               ("Cache-Control", "no-cache")]\n    if name == "sw.js":\n        headers.append(("Service-Worker-Allowed", "/"))\n    return "200 OK", headers, data\n\n\ndef _json(obj, status="200 OK"):\n    return status, [("Content-Type", "application/json; charset=utf-8"), ("Cache-Control", "no-store")], \\\n        json.dumps(obj, ensure_ascii=False).encode("utf-8")\n\n\ndef _body(environ, limit: int) -> bytes:\n    try:\n        n = int(environ.get("CONTENT_LENGTH") or 0)\n    except ValueError:\n        n = 0\n    if n > limit:\n        raise HTTPError(413, "Слишком длинная запись.")\n    return environ["wsgi.input"].read(n) if n else b""\n\n\ndef _route(environ):\n    method, path = environ.get("REQUEST_METHOD", "GET"), environ.get("PATH_INFO", "/")\n    if method == "GET":\n        if path in ("/", "/index.html"):\n            return _static("index.html")\n        if path == "/sw.js":\n            return _static("sw.js")\n        if path == "/manifest.webmanifest":\n            return "200 OK", [("Content-Type", "application/manifest+json")], _manifest()\n        if re.fullmatch(r"/icon-(?:192|512|180)\\.png", path):\n            ensure_icons()\n            return _static(path[1:])\n        raise HTTPError(404, "Нет такой страницы.")\n    if method != "POST":\n        raise HTTPError(405, "Метод не поддерживается.")\n    if path == "/api/pair":\n        _check_key(environ)\n        return _json({"ok": True, "name": "Atlas"})\n    if path == "/api/ask":\n        _check_key(environ)\n        try:\n            data = json.loads(_body(environ, 64 * 1024) or b"{}")\n        except ValueError:\n            raise HTTPError(400, "Нужен JSON.")\n        text = str(data.get("text") or "").strip()[:2000]\n        if not text:\n            raise HTTPError(400, "Пустой вопрос.")\n        return _json(_answer(text))\n    if path == "/api/transcribe":                   # ответ на карточку голосом — только текст, без мозга\n        _check_key(environ)\n        data = _body(environ, MAX_AUDIO)\n        if not data:\n            raise HTTPError(400, "Пустая запись.")\n        return _json({"text": transcribe(data, environ.get("CONTENT_TYPE", ""))})\n    from phone import panels\n    if path in panels.ROUTES:\n        _check_key(environ)\n        try:\n            data = json.loads(_body(environ, 64 * 1024) or b"{}")\n        except ValueError:\n            raise HTTPError(400, "Нужен JSON.")\n        return _json(panels.ROUTES[path](data if isinstance(data, dict) else {}))\n    if path == "/api/talk":\n        _check_key(environ)\n        data = _body(environ, MAX_AUDIO)\n        if not data:\n            raise HTTPError(400, "Пустая запись.")\n        heard = transcribe(data, environ.get("CONTENT_TYPE", ""))\n        if not heard:\n            return _json({"heard": "", "text": "", "audio": None, "mime": None})\n        print(f"[телефон] 📱 {heard}")\n        return _json(_answer(heard, heard))\n    raise HTTPError(404, "Нет такой страницы.")\n\n\n_REASON = {400: "Bad Request", 401: "Unauthorized", 404: "Not Found", 405: "Method Not Allowed", 413: "Payload Too Large",\n           500: "Internal Server Error"}\n\n\ndef app(environ, start_response):\n    try:\n        status, headers, data = _route(environ)\n    except HTTPError as e:\n        status, headers, data = _json({"error": e.message}, f"{e.status} {_REASON.get(e.status, \'Error\')}")\n    except Exception as e:\n        print(f"[телефон] ошибка: {e}")\n        status, headers, data = _json({"error": "Внутренняя ошибка Atlas."}, "500 Internal Server Error")\n    start_response(status, headers + [("Content-Length", str(len(data)))])\n    return [data]\n\n\n# =============================================================================\n# Иконки: звезда Atlas\n# =============================================================================\ndef ensure_icons() -> None:\n    try:\n        from PIL import Image, ImageDraw, ImageFilter\n    except ImportError:\n        return\n    for size in (192, 512, 180):\n        path = os.path.join(STATIC, f"icon-{size}.png")\n        if os.path.exists(path):\n            continue\n        img = Image.new("RGB", (size, size), (5, 8, 20))\n        glow = Image.new("RGB", (size, size), (0, 0, 0))\n        d = ImageDraw.Draw(glow)\n        c, r = size / 2, size * 0.30\n        d.ellipse((c - r, c - r, c + r, c + r), fill=(60, 120, 255))\n        glow = glow.filter(ImageFilter.GaussianBlur(size * 0.09))\n        img = Image.blend(img, glow, 0.85)\n        d = ImageDraw.Draw(img)\n        rr = size * 0.11\n        d.ellipse((c - rr, c - rr, c + rr, c + rr), fill=(225, 238, 255))\n        img.save(path)\n\n\n# =============================================================================\n# Запуск\n# =============================================================================\nclass _Server(socketserver.ThreadingMixIn, WSGIServer):\n    daemon_threads = True\n\n\nclass _Quiet(WSGIRequestHandler):\n    def log_message(self, *a):\n        pass\n\n\ndef start(port: int = None, host: str = "127.0.0.1") -> int:\n    """Запустить сервер. На компьютере — только для него самого (наружу выводит туннель);\n    в облаке — host="0.0.0.0". → порт."""\n    if _state["server"] is not None:\n        return _state["port"]\n    ensure_icons()\n    srv = make_server(host, PORT if port is None else port, app, server_class=_Server, handler_class=_Quiet)\n    _state.update(server=srv, port=srv.server_port)\n    _state["thread"] = threading.Thread(target=srv.serve_forever, daemon=True, name="phone-server")\n    _state["thread"].start()\n    print(f"[телефон] сервер на порту {srv.server_port}")\n    return srv.server_port\n\n\ndef stop() -> None:\n    if _state["server"] is not None:\n        _state["server"].shutdown()\n        _state["server"] = None\n\n\ndef connect(force: bool = False) -> str:\n    """Сервер + защищённый адрес. → https-адрес или "" (тогда в _state[\'hint\'] — что установить)."""\n    from phone import tunnel\n    port = start()\n    if _state["url"] and not force:\n        return _state["url"]\n    url, kind, hint = tunnel.start(port)\n    _state.update(url=url, kind=kind, hint=hint)\n    if url:\n        print(f"[телефон] адрес для телефона: {url} ({kind})")\n    else:\n        print(f"[телефон] защищённого адреса нет: {hint}")\n    return url or ""\n\n\ndef start_if_paired() -> None:\n    """При запуске Atlas: если телефон уже сопряжён — поднять сервер и адрес в фоне."""\n    if is_paired() and (os.getenv("PHONE_ENABLED") or "on").lower() not in ("off", "0", "false"):\n        threading.Thread(target=connect, daemon=True, name="phone-connect").start()\n', 'phone/static/index.html': '<!doctype html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<meta name="theme-color" content="#050814">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="Atlas">\n<link rel="manifest" href="/manifest.webmanifest">\n<link rel="apple-touch-icon" href="/icon-180.png">\n<link rel="icon" href="/icon-192.png">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;500;600&family=Literata:opsz,wght@7..72,500&display=swap" rel="stylesheet">\n<title>Atlas</title>\n<style>\n  :root {\n    --night: #050814;\n    --nebula: #141b3d;\n    --line: #263063;\n    --starlight: #e1eeff;\n    --dim: #8592bd;\n    --listen: #7cf5c4;\n    --think: #ffc46b;\n    --speak: #a9b8ff;\n    --alert: #ff8a8a;\n    --glow: #4f7dff;\n    --lvl: 0;\n    --tabbar: 64px;\n  }\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body { height: 100%; margin: 0; }\n  body {\n    background: radial-gradient(120% 70% at 50% 30%, var(--nebula) 0%, rgba(20, 27, 61, 0) 70%), var(--night);\n    color: var(--starlight);\n    font: 400 16px/1.5 "Golos Text", system-ui, -apple-system, "Segoe UI", sans-serif;\n    display: flex; flex-direction: column; overflow: hidden;\n    padding-top: env(safe-area-inset-top);\n  }\n  body::before {\n    content: ""; position: fixed; inset: 0; pointer-events: none; opacity: .5;\n    background-image:\n      radial-gradient(1px 1px at 12% 18%, #fff 50%, transparent 51%),\n      radial-gradient(1px 1px at 78% 12%, #cfe0ff 50%, transparent 51%),\n      radial-gradient(1px 1px at 64% 72%, #fff 50%, transparent 51%),\n      radial-gradient(1.5px 1.5px at 22% 64%, #dfe8ff 50%, transparent 51%),\n      radial-gradient(1px 1px at 88% 48%, #fff 50%, transparent 51%),\n      radial-gradient(1px 1px at 40% 88%, #cfe0ff 50%, transparent 51%),\n      radial-gradient(1.5px 1.5px at 52% 6%, #fff 50%, transparent 51%);\n  }\n  button { font: inherit; color: inherit; }\n  button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid var(--speak); outline-offset: 2px; }\n\n  header { display: flex; align-items: center; justify-content: space-between; padding: 12px 20px 4px; font-size: 14px; color: var(--dim); }\n  .mark { color: var(--starlight); font-weight: 600; font-size: 17px; letter-spacing: .01em; }\n  .link { display: inline-flex; align-items: center; gap: 8px; }\n  .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--dim); }\n  .link.on .dot { background: var(--listen); box-shadow: 0 0 8px var(--listen); }\n  .link.off .dot { background: var(--alert); }\n\n  main { flex: 1; min-height: 0; position: relative; }\n  .view { position: absolute; inset: 0; display: none; flex-direction: column; padding: 0 20px; overflow-y: auto;\n          padding-bottom: calc(var(--tabbar) + env(safe-area-inset-bottom) + 12px); }\n  .view.on { display: flex; }\n  .wrap { width: 100%; max-width: 560px; margin: 0 auto; }\n  h2 { font-size: 24px; font-weight: 600; margin: 14px 0 4px; }\n  .sub { color: var(--dim); font-size: 15px; margin: 0 0 16px; }\n\n  /* ---------- Atlas: звезда ---------- */\n  #v-atlas { align-items: center; overflow: hidden; }\n  .star { --c: var(--glow); position: relative; flex: none; margin-top: 2vh; width: min(52vw, 250px); aspect-ratio: 1;\n          border: 0; padding: 0; border-radius: 50%; background: transparent; cursor: pointer; }\n  .halo, .core, .ring { position: absolute; border-radius: 50%; pointer-events: none; }\n  .halo { inset: 0; background: radial-gradient(circle, color-mix(in srgb, var(--c) 70%, transparent) 0%,\n          color-mix(in srgb, var(--c) 18%, transparent) 42%, transparent 70%);\n          transform: scale(calc(.82 + var(--lvl) * .5)); transition: transform .08s linear, background .6s ease; }\n  .core { inset: 38%; background: radial-gradient(circle at 42% 38%, #fff 0%, var(--starlight) 35%,\n          color-mix(in srgb, var(--c) 55%, var(--starlight)) 100%);\n          box-shadow: 0 0 34px 8px color-mix(in srgb, var(--c) 60%, transparent); transition: box-shadow .6s ease, background .6s ease; }\n  .ring { inset: 22%; border: 1.5px solid transparent; opacity: 0; border-top-color: var(--c);\n          border-right-color: color-mix(in srgb, var(--c) 40%, transparent); transition: opacity .3s ease; }\n  body[data-state="idle"] .halo { animation: breathe 5s ease-in-out infinite; }\n  body[data-state="listening"] .star { --c: var(--listen); }\n  body[data-state="thinking"] .star { --c: var(--think); }\n  body[data-state="thinking"] .ring { opacity: 1; animation: orbit 1.6s linear infinite; }\n  body[data-state="speaking"] .star { --c: var(--speak); }\n  body[data-state="speaking"] .halo { animation: voice .5s ease-in-out infinite alternate; }\n  body[data-state="locked"] .star { --c: #2a3566; cursor: default; }\n  @keyframes breathe { 50% { transform: scale(.9); } }\n  @keyframes orbit { to { transform: rotate(360deg); } }\n  @keyframes voice { from { transform: scale(.86); } to { transform: scale(1.02); } }\n\n  .caption { margin: 2vh 0 0; max-width: 34ch; min-height: 2.9em; text-align: center; font-size: 19px; line-height: 1.45;\n             font-weight: 500; text-wrap: balance; }\n  .caption .heard { display: block; color: var(--dim); font-size: 15px; font-weight: 400; margin-bottom: 6px; }\n  .hint { color: var(--dim); font-size: 15px; font-weight: 400; }\n  .chips { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin: 14px 0 0; }\n  .chip { border: 1px solid var(--line); background: color-mix(in srgb, var(--nebula) 70%, transparent);\n          border-radius: 999px; padding: 7px 14px; font-size: 15px; cursor: pointer; }\n  .chip:disabled { opacity: .4; }\n  .install { margin-top: 12px; border: 1px solid color-mix(in srgb, var(--starlight) 35%, transparent);\n             background: transparent; border-radius: 999px; padding: 7px 16px; font-size: 15px; cursor: pointer; }\n  .install[hidden] { display: none; }\n  .history { flex: 1; min-height: 0; width: 100%; max-width: 560px; margin-top: 12px; overflow-y: auto; padding: 8px 2px 4px;\n             font-size: 15px; mask-image: linear-gradient(to bottom, transparent 0, #000 24px); }\n  .turn { margin: 0 0 12px; max-width: 82%; }\n  .turn.you { margin-left: auto; text-align: right; color: var(--dim); }\n  .ask { display: flex; gap: 10px; width: 100%; max-width: 560px; padding: 8px 0 4px; }\n\n  input, textarea {\n    flex: 1; min-width: 0; font: inherit; color: var(--starlight); background: color-mix(in srgb, var(--nebula) 80%, transparent);\n    border: 1px solid var(--line); border-radius: 14px; padding: 11px 14px; }\n  textarea { resize: none; min-height: 84px; }\n  input::placeholder, textarea::placeholder { color: var(--dim); }\n  .btn { border: 0; border-radius: 14px; padding: 0 18px; min-height: 44px; font-weight: 600; background: var(--starlight);\n         color: var(--night); cursor: pointer; }\n  .btn:disabled { opacity: .4; }\n  .btn.quiet { background: transparent; color: var(--starlight); border: 1px solid var(--line); font-weight: 500; }\n\n  /* ---------- списки ---------- */\n  .row { display: flex; gap: 10px; margin-bottom: 14px; }\n  ul.list { list-style: none; margin: 0; padding: 0; }\n  ul.list li { display: flex; align-items: flex-start; gap: 12px; padding: 12px 0; border-bottom: 1px solid color-mix(in srgb, var(--line) 60%, transparent); }\n  .check { flex: none; width: 26px; height: 26px; margin-top: 1px; border-radius: 50%; border: 1.5px solid var(--dim);\n           background: transparent; cursor: pointer; display: grid; place-items: center; padding: 0; }\n  .check svg { opacity: 0; }\n  li.done .check { border-color: var(--listen); background: color-mix(in srgb, var(--listen) 20%, transparent); }\n  li.done .check svg { opacity: 1; }\n  li.done .what { color: var(--dim); text-decoration: line-through; }\n  .what { flex: 1; min-width: 0; overflow-wrap: anywhere; white-space: pre-wrap; }\n  .del { flex: none; border: 0; background: transparent; color: var(--dim); cursor: pointer; width: 32px; height: 32px;\n         border-radius: 8px; padding: 0; display: grid; place-items: center; }\n  .empty { color: var(--dim); padding: 18px 0; }\n\n  /* ---------- учёба ---------- */\n  .streak { color: var(--dim); font-size: 15px; margin: 0 0 14px; }\n  .deck { display: flex; align-items: center; gap: 12px; padding: 14px 0; border-bottom: 1px solid color-mix(in srgb, var(--line) 60%, transparent); }\n  .deck .name { flex: 1; font-weight: 500; }\n  .deck .meta { color: var(--dim); font-size: 14px; font-weight: 400; display: block; }\n  .session[hidden], .decks[hidden] { display: none; }\n  .progress { height: 3px; background: var(--line); border-radius: 2px; margin: 6px 0 18px; overflow: hidden; }\n  .progress i { display: block; height: 100%; width: 0; background: var(--listen); transition: width .3s ease; }\n  .card { border: 1px solid var(--line); border-radius: 20px; padding: 28px 22px; min-height: 180px;\n          background: linear-gradient(180deg, color-mix(in srgb, var(--nebula) 90%, transparent), color-mix(in srgb, var(--night) 80%, transparent));\n          display: flex; flex-direction: column; justify-content: center; }\n  .card .deckname { color: var(--dim); font-size: 14px; margin-bottom: 10px; }\n  .card .front { font-family: "Literata", Georgia, serif; font-size: 30px; line-height: 1.25; font-weight: 500; overflow-wrap: anywhere; }\n  .feedback { min-height: 3em; margin: 16px 2px 0; font-size: 17px; }\n  .feedback.ok { color: var(--listen); }\n  .feedback.miss { color: var(--think); }\n  .answer-row { display: flex; gap: 10px; margin-top: 8px; }\n  .mic { flex: none; width: 48px; border-radius: 14px; border: 1px solid var(--line); background: transparent; cursor: pointer;\n         display: grid; place-items: center; }\n  .mic.rec { border-color: var(--listen); background: color-mix(in srgb, var(--listen) 18%, transparent); }\n  .study-actions { display: flex; gap: 10px; margin-top: 12px; }\n\n  /* ---------- нижняя панель ---------- */\n  nav { position: fixed; left: 0; right: 0; bottom: 0; height: calc(var(--tabbar) + env(safe-area-inset-bottom));\n        padding-bottom: env(safe-area-inset-bottom); display: flex; justify-content: center;\n        background: color-mix(in srgb, var(--night) 88%, transparent); backdrop-filter: blur(12px);\n        border-top: 1px solid color-mix(in srgb, var(--line) 70%, transparent); }\n  nav .tabs { display: flex; width: 100%; max-width: 560px; }\n  nav button { flex: 1; border: 0; background: transparent; color: var(--dim); display: flex; flex-direction: column;\n               align-items: center; justify-content: center; gap: 3px; font-size: 12px; cursor: pointer; position: relative; }\n  nav button[aria-current="page"] { color: var(--starlight); }\n  nav button[aria-current="page"] svg { stroke: var(--starlight); }\n  nav .badge { position: absolute; top: 9px; left: calc(50% + 8px); min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px;\n               background: var(--think); color: var(--night); font-size: 11px; font-weight: 600; line-height: 16px; }\n  nav .badge[hidden] { display: none; }\n  svg.i { width: 22px; height: 22px; fill: none; stroke: var(--dim); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n\n  @media (prefers-reduced-motion: reduce) { .halo, .ring { animation: none !important; transition: none; } }\n</style>\n</head>\n<body data-state="locked">\n<header>\n  <span class="mark">atlas</span>\n  <span class="link" id="link"><span class="dot"></span><span id="linkText">не сопряжено</span></span>\n</header>\n\n<main>\n  <section class="view on" id="v-atlas" aria-label="Atlas">\n    <button class="star" id="star" aria-label="Говорить с Atlas" disabled>\n      <span class="halo"></span><span class="ring"></span><span class="core"></span>\n    </button>\n    <p class="caption" id="caption" aria-live="polite"></p>\n    <div class="chips" id="chips">\n      <button class="chip" data-ask="Какая сейчас погода?" disabled>Погода</button>\n      <button class="chip" data-ask="Что у меня на сегодня?" disabled>Что на сегодня</button>\n      <button class="chip" data-tab="study" disabled>Повторить SAT</button>\n    </div>\n    <button class="install" id="install" hidden>Установить на телефон</button>\n    <section class="history" id="history" aria-label="История разговора"></section>\n    <form class="ask" id="askForm" autocomplete="off">\n      <input id="askText" placeholder="Или напиши…" aria-label="Вопрос Atlas текстом" disabled>\n      <button class="btn" id="askSend" disabled>Спросить</button>\n    </form>\n  </section>\n\n  <section class="view" id="v-todos" aria-label="Дела">\n    <div class="wrap">\n      <h2>Дела</h2>\n      <p class="sub">Те же, что Atlas помнит голосом: «добавь в дела…».</p>\n      <form class="row" id="todoForm" autocomplete="off">\n        <input id="todoText" placeholder="Новое дело" aria-label="Новое дело">\n        <button class="btn">Добавить</button>\n      </form>\n      <ul class="list" id="todoList"></ul>\n    </div>\n  </section>\n\n  <section class="view" id="v-notes" aria-label="Заметки">\n    <div class="wrap">\n      <h2>Заметки</h2>\n      <p class="sub">Записывай мысль здесь или скажи Atlas «запиши заметку…».</p>\n      <form id="noteForm" autocomplete="off">\n        <div class="row"><textarea id="noteText" placeholder="Текст заметки" aria-label="Текст заметки"></textarea></div>\n        <div class="row"><button class="btn">Сохранить заметку</button></div>\n      </form>\n      <ul class="list" id="noteList"></ul>\n    </div>\n  </section>\n\n  <section class="view" id="v-study" aria-label="Учёба">\n    <div class="wrap">\n      <div class="decks" id="decks">\n        <h2>Учёба</h2>\n        <p class="streak" id="streak"></p>\n        <div id="deckList"></div>\n      </div>\n      <div class="session" id="session" hidden>\n        <h2 id="sessTitle">Тренировка</h2>\n        <div class="progress"><i id="bar"></i></div>\n        <div class="card"><div class="deckname" id="cardDeck"></div><div class="front" id="cardFront"></div></div>\n        <p class="feedback" id="feedback" aria-live="polite"></p>\n        <form class="answer-row" id="answerForm" autocomplete="off">\n          <input id="answerText" placeholder="Твой ответ" aria-label="Ответ на карточку">\n          <button type="button" class="mic" id="answerMic" aria-label="Ответить голосом">\n            <svg class="i" viewBox="0 0 24 24"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg>\n          </button>\n          <button class="btn">Проверить</button>\n        </form>\n        <div class="study-actions">\n          <button class="btn quiet" id="showAnswer">Показать ответ</button>\n          <button class="btn quiet" id="stopStudy">Закончить</button>\n        </div>\n      </div>\n    </div>\n  </section>\n</main>\n\n<nav aria-label="Разделы">\n  <div class="tabs">\n    <button data-view="atlas" aria-current="page">\n      <svg class="i" viewBox="0 0 24 24"><circle cx="12" cy="12" r="3.5"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/></svg>Atlas</button>\n    <button data-view="todos">\n      <svg class="i" viewBox="0 0 24 24"><path d="M9 6h11M9 12h11M9 18h11"/><path d="M3.5 6l1.5 1.5L7.5 5M3.5 12l1.5 1.5 2.5-2.5"/><circle cx="5" cy="18" r="1.3"/></svg>Дела<span class="badge" id="todoBadge" hidden></span></button>\n    <button data-view="notes">\n      <svg class="i" viewBox="0 0 24 24"><path d="M6 3h9l4 4v14H6z"/><path d="M15 3v4h4M9 12h7M9 16h5"/></svg>Заметки</button>\n    <button data-view="study">\n      <svg class="i" viewBox="0 0 24 24"><rect x="3" y="6" width="14" height="12" rx="2"/><path d="M7 3h12a2 2 0 0 1 2 2v10"/></svg>Учёба<span class="badge" id="studyBadge" hidden></span></button>\n  </div>\n</nav>\n\n<audio id="player" playsinline></audio>\n\n<script>\n(() => {\n  const $ = (id) => document.getElementById(id);\n  const body = document.body, star = $("star"), caption = $("caption"), historyEl = $("history"), player = $("player");\n  const KEY = "atlasKey";\n  let key = localStorage.getItem(KEY) || "";\n  let busy = false, rec = null, paired = false, data = null;\n\n  const setState = (s) => { body.dataset.state = s; };\n  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };\n  const say = (text, heard) => { caption.innerHTML = ""; if (heard) caption.append(el("span", "heard", heard)); caption.append(document.createTextNode(text || "")); };\n  const hint = (text) => { caption.innerHTML = ""; caption.append(el("span", "hint", text)); };\n  const addTurn = (who, text) => { if (!text) return; historyEl.append(el("p", "turn " + who, text)); historyEl.scrollTop = historyEl.scrollHeight; };\n  let shown = [];                                  // реплики под звездой; в историю уходят, когда начинается следующая\n  const archive = () => { shown.forEach(([w, t]) => addTurn(w, t)); shown = []; };\n  const plural = (n, one, few, many) => { const a = n % 10, b = n % 100;\n    return `${n} ${a === 1 && b !== 11 ? one : a >= 2 && a <= 4 && (b < 12 || b > 14) ? few : many}`; };\n  const link = (on, text) => { $("link").className = "link " + (on ? "on" : "off"); $("linkText").textContent = text; };\n  const unlock = (on) => {\n    paired = on;\n    document.querySelectorAll("#star, #askText, #askSend, .chip").forEach((b) => (b.disabled = !on));\n    setState(on ? "idle" : "locked");\n  };\n\n  async function api(path, payload, raw) {\n    const opts = { method: "POST", headers: { "X-Atlas-Key": key } };\n    if (raw) { opts.body = raw; opts.headers["Content-Type"] = raw.type; }\n    else if (payload !== undefined) { opts.body = JSON.stringify(payload); opts.headers["Content-Type"] = "application/json"; }\n    const r = await fetch(path, opts);\n    if (r.status === 401) {\n      link(false, "ключ устарел"); unlock(false);\n      hint("Ключ устарел. Скажи Атласу на компьютере «установи себя на телефон» и отсканируй QR-код заново.");\n      throw new Error("401");\n    }\n    if (!r.ok) throw new Error(String(r.status));\n    return r.json();\n  }\n\n  // ---------- вкладки ----------\n  function show(view) {\n    document.querySelectorAll(".view").forEach((v) => v.classList.toggle("on", v.id === "v-" + view));\n    document.querySelectorAll("nav button").forEach((b) => {\n      if (b.dataset.view === view) b.setAttribute("aria-current", "page"); else b.removeAttribute("aria-current");\n    });\n    if (view !== "atlas") refresh();\n  }\n  document.querySelectorAll("nav button").forEach((b) => b.addEventListener("click", () => show(b.dataset.view)));\n\n  // ---------- сопряжение ----------\n  async function pair() {\n    const q = new URLSearchParams(location.search).get("pair");\n    if (q) { key = q; localStorage.setItem(KEY, q); window.history.replaceState(null, "", "/"); }\n    if (!key) { link(false, "не сопряжено"); hint("Скажи Атласу на компьютере «Установи себя на телефон» и отсканируй QR-код."); return; }\n    try {\n      await api("/api/pair");\n      link(true, "на связи"); unlock(true);\n      hint(q ? "Готово. Нажми на звезду и говори." : "Нажми на звезду и говори.");\n      refresh();\n    } catch (e) {\n      if (e.message !== "401") { link(false, "нет связи"); hint("Нет связи с Atlas. Облаку иногда нужна минута, чтобы проснуться, — попробуй ещё раз."); }\n    }\n  }\n\n  // ---------- разговор ----------\n  function unlockAudio() { try { player.muted = true; player.play().catch(() => {}); player.pause(); player.muted = false; } catch (e) {} }\n  function speak(res) {\n    return new Promise((done) => {\n      if (res.audio) {\n        const bytes = Uint8Array.from(atob(res.audio), (c) => c.charCodeAt(0));\n        player.src = URL.createObjectURL(new Blob([bytes], { type: res.mime || "audio/mpeg" }));\n        setState("speaking"); player.onended = player.onerror = () => done();\n        player.play().catch(() => done());\n      } else if (res.text && "speechSynthesis" in window) {\n        const u = new SpeechSynthesisUtterance(res.text); u.lang = /[а-яё]/i.test(res.text) ? "ru-RU" : "en-US";\n        setState("speaking"); u.onend = u.onerror = () => done(); speechSynthesis.speak(u);\n      } else done();\n    });\n  }\n  async function handle(promise, typed) {\n    busy = true; setState("thinking"); archive(); if (typed) { say("", typed); shown.push(["you", typed]); }\n    try {\n      const res = await promise;\n      if (res.heard === "") { hint("Не расслышал. Нажми на звезду и повтори."); return; }\n      if (res.heard) shown.push(["you", res.heard]);\n      say(res.text, res.heard || typed); shown.push(["atlas", res.text]);\n      await speak(res);\n      refresh();                                   // «добавь в дела…» голосом — списки уже свежие\n    } catch (e) {\n      if (e.message !== "401") hint("Не получилось связаться с Atlas. Попробуй ещё раз.");\n    } finally { busy = false; if (paired) setState("idle"); }\n  }\n  const ask = (t) => { unlockAudio(); handle(api("/api/ask", { text: t }), t); };\n\n  // запись голоса: тишина 1,2 с — конец фразы; onDone(запись или null, почему)\n  const MIME = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", "audio/ogg;codecs=opus"]\n    .find((m) => window.MediaRecorder && MediaRecorder.isTypeSupported(m)) || "";\n  async function record(onLevel, onDone) {\n    let stream;\n    try { stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } }); }\n    catch (e) { onDone(null, "Нет доступа к микрофону. Разреши его в настройках браузера для этого сайта."); return null; }\n    const chunks = []; const mr = new MediaRecorder(stream, MIME ? { mimeType: MIME } : undefined);\n    const ctx = new (window.AudioContext || window.webkitAudioContext)();\n    const an = ctx.createAnalyser(); an.fftSize = 1024; ctx.createMediaStreamSource(stream).connect(an);\n    const buf = new Float32Array(an.fftSize);\n    let spoke = false, quietSince = 0, live = true; const t0 = performance.now();\n    const ctl = { stop: () => mr.state === "recording" && mr.stop() };\n    mr.ondataavailable = (e) => e.data.size && chunks.push(e.data);\n    mr.onstop = () => {\n      live = false; stream.getTracks().forEach((t) => t.stop()); ctx.close(); onLevel(0);\n      onDone(spoke ? new Blob(chunks, { type: mr.mimeType || MIME || "audio/webm" }) : null, spoke ? "" : "Ничего не услышал.");\n    };\n    mr.start(250);\n    (function meter() {\n      if (!live) return;\n      an.getFloatTimeDomainData(buf);\n      let s = 0; for (const v of buf) s += v * v; const rms = Math.sqrt(s / buf.length);\n      onLevel(Math.min(1, rms * 9));\n      const now = performance.now();\n      if (rms > 0.025) { spoke = true; quietSince = 0; } else if (spoke && !quietSince) quietSince = now;\n      if ((spoke && quietSince && now - quietSince > 1200) || now - t0 > 15000 || (!spoke && now - t0 > 7000)) return ctl.stop();\n      requestAnimationFrame(meter);\n    })();\n    return ctl;\n  }\n  const level = (v) => document.documentElement.style.setProperty("--lvl", v.toFixed(3));\n\n  star.addEventListener("click", async () => {\n    if (rec) return rec.stop();                     // второе нажатие — отправить сразу\n    if (busy) { player.pause(); if (window.speechSynthesis) speechSynthesis.cancel(); return; }\n    unlockAudio(); setState("listening"); say("Слушаю…");\n    archive();\n    rec = await record(level, (blob, why) => {\n      rec = null;\n      if (!blob) { setState("idle"); hint(why + " Нажми на звезду и говори."); return; }\n      handle(api("/api/talk", undefined, blob));\n    });\n  });\n  $("askForm").addEventListener("submit", (e) => {\n    e.preventDefault(); const t = $("askText").value.trim(); if (!t || busy) return;\n    $("askText").value = ""; ask(t);\n  });\n  document.querySelectorAll(".chip").forEach((c) => c.addEventListener("click", () => {\n    if (c.dataset.tab === "study") { show("study"); startStudy(pickDeck("sat")); return; }\n    if (!busy) ask(c.dataset.ask);\n  }));\n\n  // ---------- данные экранов ----------\n  async function refresh() {\n    if (!paired) return;\n    try { render(await api("/api/home")); } catch (e) {}\n  }\n  const iconCheck = \'<svg class="i" viewBox="0 0 24 24" style="width:16px;height:16px;stroke:var(--listen)"><path d="M5 12l4 4 10-10"/></svg>\';\n  const iconDel = \'<svg class="i" viewBox="0 0 24 24" style="width:18px;height:18px"><path d="M6 6l12 12M18 6L6 18"/></svg>\';\n  const send = (path, payload) => api(path, payload).then(render).catch(() => {});\n\n  function render(d) {\n    data = d;\n    const tl = $("todoList"); tl.innerHTML = "";\n    if (!d.todos.length) tl.append(el("li", "empty", "Дел нет. Добавь первое или скажи Atlas «добавь в дела…»."));\n    d.todos.forEach((t, i) => {\n      const li = el("li", t.done ? "done" : "");\n      const c = el("button", "check"); c.innerHTML = iconCheck;\n      c.setAttribute("aria-label", t.done ? "Сделано" : "Отметить сделанным: " + t.task); c.disabled = t.done;\n      c.addEventListener("click", () => send("/api/todo/done", { i: i + 1 }));\n      const x = el("button", "del"); x.innerHTML = iconDel; x.setAttribute("aria-label", "Удалить дело: " + t.task);\n      x.addEventListener("click", () => send("/api/todo/delete", { i: i + 1 }));\n      li.append(c, el("span", "what", t.task), x); tl.append(li);\n    });\n    const open = d.todos.filter((t) => !t.done).length;\n    $("todoBadge").hidden = !open; $("todoBadge").textContent = open;\n\n    const nl = $("noteList"); nl.innerHTML = "";\n    if (!d.notes.length) nl.append(el("li", "empty", "Заметок нет."));\n    d.notes.map((n, i) => [n, i]).reverse().forEach(([n, i]) => {      // свежие сверху\n      const li = el("li"); const x = el("button", "del"); x.innerHTML = iconDel; x.setAttribute("aria-label", "Удалить заметку");\n      x.addEventListener("click", () => send("/api/note/delete", { i: i + 1 }));\n      li.append(el("span", "what", n), x); nl.append(li);\n    });\n\n    const due = d.decks.reduce((s, k) => s + (k.due || 0), 0);\n    $("studyBadge").hidden = !due; $("studyBadge").textContent = due;\n    if ($("session").hidden)\n      $("streak").textContent = (due ? `К повторению сегодня: ${due}.` : "На сегодня всё повторено.")\n        + (d.streak > 1 ? ` Серия: ${d.streak} дн. подряд.` : "");\n    const dl = $("deckList"); dl.innerHTML = "";\n    if (!d.decks.length) dl.append(el("p", "empty", "Колод пока нет. Скажи Atlas: «сделай 10 карточек по SAT-словам»."));\n    d.decks.forEach((k) => {\n      const row = el("div", "deck"); const name = el("span", "name", k.deck);\n      name.append(el("span", "meta", `${plural(k.total, "карточка", "карточки", "карточек")}, к повторению ${k.due}, выучено ${k.learned}`));\n      const go = el("button", "btn" + (k.due ? "" : " quiet"), "Повторить");\n      go.addEventListener("click", () => startStudy(k.deck));\n      row.append(name, go); dl.append(row);\n    });\n    if (d.study && $("session").hidden) showCard(d.study);          // тренировка уже идёт — продолжаем её\n  }\n  const pickDeck = (name) => { const k = ((data && data.decks) || []).find((x) => x.deck.toLowerCase().includes(name)); return k ? k.deck : ""; };\n\n  $("todoForm").addEventListener("submit", (e) => {\n    e.preventDefault(); const t = $("todoText").value.trim(); if (!t) return;\n    $("todoText").value = ""; send("/api/todo/add", { task: t });\n  });\n  $("noteForm").addEventListener("submit", (e) => {\n    e.preventDefault(); const t = $("noteText").value.trim(); if (!t) return;\n    $("noteText").value = ""; send("/api/note/add", { text: t });\n  });\n\n  // ---------- тренировка ----------\n  function showCard(c) {\n    $("decks").hidden = true; $("session").hidden = false;\n    $("sessTitle").textContent = `Карточка ${c.n} из ${c.total}`;\n    $("bar").style.width = Math.round(((c.n - 1) / c.total) * 100) + "%";\n    $("cardDeck").textContent = c.deck; $("cardFront").textContent = c.front;\n    $("answerText").value = "";\n  }\n  function endStudy(msg) {\n    $("session").hidden = true; $("decks").hidden = false;\n    refresh().then(() => { if (msg) $("streak").textContent = msg; });\n  }\n  function studyResult(r) {\n    const fb = $("feedback"); fb.textContent = r.feedback || "";\n    fb.className = "feedback " + (/^(верно|точно|так и есть|правильно|correct|right|exactly|spot on)/i.test(r.feedback || "") ? "ok" : "miss");\n    if (r.done) { $("bar").style.width = "100%"; setTimeout(() => endStudy(r.feedback), 1800); return; }\n    if (r.card) showCard(r.card);\n  }\n  async function startStudy(deck) {\n    $("feedback").textContent = "";\n    try {\n      const r = await api("/api/study/start", { deck });\n      if (r.card) showCard(r.card); else endStudy(r.feedback);\n    } catch (e) {}\n  }\n  const answerCard = (text) => api("/api/study/answer", { text }).then(studyResult).catch(() => {});\n  $("answerForm").addEventListener("submit", (e) => { e.preventDefault(); const t = $("answerText").value.trim(); if (t) answerCard(t); });\n  $("showAnswer").addEventListener("click", () => answerCard(""));\n  $("stopStudy").addEventListener("click", () => api("/api/study/stop").then((r) => endStudy(r.feedback)).catch(() => {}));\n  let ansRec = null;\n  $("answerMic").addEventListener("click", async () => {\n    if (ansRec) return ansRec.stop();\n    $("answerMic").classList.add("rec"); $("feedback").className = "feedback"; $("feedback").textContent = "Слушаю ответ…";\n    ansRec = await record(() => {}, async (blob, why) => {\n      ansRec = null; $("answerMic").classList.remove("rec");\n      if (!blob) { $("feedback").textContent = why; return; }\n      try {\n        const r = await api("/api/transcribe", undefined, blob);\n        $("answerText").value = r.text || "";\n        if (r.text) answerCard(r.text); else $("feedback").textContent = "Не расслышал — повтори или напиши.";\n      } catch (e) {}\n    });\n  });\n\n  // ---------- установка ----------\n  let deferred = null;\n  window.addEventListener("beforeinstallprompt", (e) => { e.preventDefault(); deferred = e; $("install").hidden = false; });\n  $("install").addEventListener("click", async () => { if (!deferred) return; deferred.prompt(); await deferred.userChoice; deferred = null; $("install").hidden = true; });\n  const standalone = matchMedia("(display-mode: standalone)").matches || navigator.standalone;\n  if (/iphone|ipad|ipod/i.test(navigator.userAgent) && !standalone)\n    setTimeout(() => addTurn("atlas", "Чтобы установить Atlas на iPhone: кнопка «Поделиться» внизу Safari → «На экран „Домой“»."), 1200);\n  if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => {});\n  document.addEventListener("visibilitychange", () => { if (!document.hidden) refresh(); });\n\n  pair();\n})();\n</script>\n</body>\n</html>\n', 'phone/static/sw.js': '// Atlas: оболочка приложения работает и без сети (звезда, подсказка), разговор — только с сетью.\nconst SHELL = "atlas-shell-v2";        // v2: вкладки дел, заметок и учёбы\nconst FILES = ["/", "/manifest.webmanifest", "/icon-192.png", "/icon-512.png", "/icon-180.png"];\n\nself.addEventListener("install", (e) => {\n  e.waitUntil(caches.open(SHELL).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));\n});\nself.addEventListener("activate", (e) => {\n  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== SHELL).map((k) => caches.delete(k))))\n    .then(() => self.clients.claim()));\n});\nself.addEventListener("fetch", (e) => {\n  const url = new URL(e.request.url);\n  if (url.origin !== location.origin || url.pathname.startsWith("/api/")) return;   // разговор — всегда по сети\n  if (e.request.mode === "navigate") {\n    e.respondWith(fetch(e.request).catch(() => caches.match("/")));                    // свежая страница, без сети — из кэша\n    return;\n  }\n  e.respondWith(caches.match(e.request).then((hit) => hit || fetch(e.request)));\n});\n', 'tests/test_phone.py': '"""\nТесты Atlas на телефоне: сервер (как его видит телефон), туннель и команда «установи себя».\n\n    python tests/test_phone.py\n\nСервер запускается по-настоящему на свободном порту; мозг, распознавание, голос и туннели —\nподставные (интернет, ключи и Windows не нужны).\n"""\nimport base64\nimport json\nimport os\nimport sys\nimport tempfile\nimport traceback\nimport types\nimport urllib.error\nimport urllib.request\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nLOG = {"ask": [], "tts": [], "stt": [], "opened": []}\nFAST = {"открой блокнот": "Открываю блокнот."}\n\n\ndef _mod(name, **attrs):\n    m = types.ModuleType(name)\n    m.__dict__.update(attrs)\n    sys.modules[name] = m\n    return m\n\n\ndef install():\n    _mod("fast_commands", try_fast_command=lambda t: FAST.get(t.lower().strip(" .!?")))\n    _mod("ai_brain", ask_ai=lambda q, speech=None: (LOG["ask"].append(q), REPLY[0])[1],\n         remember_exchange=lambda u, a: None)\n\n    class _Tr:\n        @staticmethod\n        def create(**kw):\n            LOG["stt"].append(kw)\n            return types.SimpleNamespace(text=HEARD[0])\n\n    def gen(text, filename):\n        LOG["tts"].append(text)\n        if TTS_FAIL[0]:\n            raise RuntimeError("нет голоса")\n        with open(filename, "wb") as f:\n            f.write(b"MP3DATA")\n        return filename\n    _mod("voice", groq_client=types.SimpleNamespace(audio=types.SimpleNamespace(transcriptions=_Tr)),\n         STT_WHISPER="whisper-large-v3", _stt_language=lambda: "ru", _stt_prompt=lambda: "подсказка",\n         _WHISPER_JUNK={"продолжение следует"}, _generate_any=gen, get_response_language=lambda: "ru")\n    _mod("ui_state", shared_state={"chat_history": []})\n    core = sys.modules.get("core") or _mod("core")\n    core.__path__ = [os.path.join(ROOT, "core")]                 # настоящие core/emotions.py, если есть\n    _mod("core.memory", log_turn=lambda who, t: None)\n    core.memory = sys.modules["core.memory"]\n\n\nREPLY, HEARD, TTS_FAIL = ["Готово."], ["какая погода"], [False]\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\ndef call(path, method="GET", body=None, headers=None):\n    req = urllib.request.Request(BASE + path, data=body, method=method, headers=headers or {})\n    try:\n        with urllib.request.urlopen(req, timeout=10) as r:\n            return r.status, dict(r.headers), r.read()\n    except urllib.error.HTTPError as e:\n        return e.code, dict(e.headers), e.read()\n\n\ndef ask(text, key=None):\n    return call("/api/ask", "POST", json.dumps({"text": text}).encode(),\n                {"Content-Type": "application/json", "X-Atlas-Key": key if key is not None else TOKEN})\n\n\n@test\ndef app_files_for_installing():\n    st, h, b = call("/")\n    assert st == 200 and \'id="star"\' in b.decode() and h["Content-Type"].startswith("text/html")\n    st, h, b = call("/manifest.webmanifest")\n    man = json.loads(b)\n    assert st == 200 and man["display"] == "standalone" and man["start_url"] == "/" and len(man["icons"]) == 2\n    st, h, b = call("/sw.js")\n    assert st == 200 and h.get("Service-Worker-Allowed") == "/" and b"caches" in b\n    st, h, b = call("/icon-192.png")\n    assert st == 200 and b[:8] == b"\\x89PNG\\r\\n\\x1a\\n", "иконка-звезда"\n\n\n@test\ndef nothing_without_the_pairing_key():\n    for key in ("", "wrong-key"):\n        st, _, b = ask("какая погода", key=key)\n        assert st == 401 and "ключ" in json.loads(b)["error"], (key, st)\n    st, _, _ = call("/api/talk", "POST", b"audio", {"Content-Type": "audio/webm", "X-Atlas-Key": "nope"})\n    assert st == 401\n    assert call("/pair")[0] == 404 and call("/phone_pairing.json")[0] == 404, "ключ по сети не отдаётся"\n    assert not LOG["ask"], "без ключа мозг не вызывался"\n\n\n@test\ndef pairing_check():\n    st, _, b = call("/api/pair", "POST", b"", {"X-Atlas-Key": TOKEN})\n    assert st == 200 and json.loads(b)["ok"]\n\n\n@test\ndef text_question_fast_path_answers_with_voice():\n    LOG["ask"].clear()\n    st, _, b = ask("Открой блокнот.")\n    r = json.loads(b)\n    assert st == 200 and r["text"] == "Открываю блокнот." and not LOG["ask"], "быстрый путь, без модели"\n    assert base64.b64decode(r["audio"]) == b"MP3DATA" and r["mime"] == "audio/mpeg"\n\n\n@test\ndef text_question_goes_to_the_brain_and_back():\n    LOG["ask"].clear()\n    LOG["tts"].clear()\n    REPLY[0] = "[warm] Тепло, сэр."\n    st, _, b = ask("какая погода")\n    r = json.loads(b)\n    assert len(LOG["ask"]) == 1 and LOG["ask"][0].startswith("(Respond in Russian.) (Said on the phone:") \\\n        and LOG["ask"][0].endswith("какая погода"), LOG["ask"]\n    emotions = os.path.exists(os.path.join(ROOT, "core", "emotions.py"))\n    assert r["text"] == ("Тепло, сэр." if emotions else "[warm] Тепло, сэр."), r["text"]\n    assert LOG["tts"][-1] == "[warm] Тепло, сэр.", "голосу метки нужны"\n    chat = sys.modules["ui_state"].shared_state["chat_history"]\n    assert ("You 📱", "какая погода") in chat, "разговор виден и в окне на компьютере"\n\n\n@test\ndef voice_question_from_android_and_iphone():\n    for ctype, ext in (("audio/webm;codecs=opus", "webm"), ("audio/mp4", "m4a")):\n        LOG["stt"].clear()\n        HEARD[0], REPLY[0] = "какая погода", "Солнечно."\n        st, _, b = call("/api/talk", "POST", b"\\x1a\\x45\\xdf\\xa3audio", {"Content-Type": ctype, "X-Atlas-Key": TOKEN})\n        r = json.loads(b)\n        assert st == 200 and r["heard"] == "какая погода" and r["text"] == "Солнечно.", r\n        kw = LOG["stt"][0]\n        assert kw["file"][0] == f"phone.{ext}" and kw["language"] == "ru" and kw["file"][1].startswith(b"\\x1a"), kw\n\n\n@test\ndef noise_is_not_sent_to_the_brain():\n    LOG["ask"].clear()\n    HEARD[0] = "Продолжение следует..."\n    st, _, b = call("/api/talk", "POST", b"noise", {"Content-Type": "audio/webm", "X-Atlas-Key": TOKEN})\n    assert st == 200 and json.loads(b)["heard"] == "" and not LOG["ask"]\n    HEARD[0] = "какая погода"\n\n\n@test\ndef too_long_recording_is_refused_and_server_keeps_working():\n    big = b"0" * (S.MAX_AUDIO + 10)\n    try:                                   # сервер отказывает, не дочитывая: 413 или обрыв соединения\n        st, _, _ = call("/api/talk", "POST", big, {"Content-Type": "audio/webm", "X-Atlas-Key": TOKEN})\n        assert st == 413, st\n    except OSError:                        # Linux: ошибка отправки; Windows: ConnectionResetError при чтении ответа\n        pass\n    LOG["ask"].clear()\n    st, _, b = ask("какая погода")\n    assert st == 200 and LOG["ask"], "после отказа сервер отвечает как обычно"\n\n\n@test\ndef phone_speaks_by_itself_when_atlas_voice_fails():\n    TTS_FAIL[0] = True\n    try:\n        st, _, b = ask("какая погода")\n        r = json.loads(b)\n        assert st == 200 and r["audio"] is None and r["text"], r\n    finally:\n        TTS_FAIL[0] = False\n\n\n@test\ndef phone_answers_short_in_the_language_spoken_and_pc_stays_quiet():\n    import time as _t\n    v = sys.modules["voice"]\n    saved = v.get_response_language\n    v.get_response_language = lambda: "en"                 # в настройках компьютера — английский\n    try:\n        LOG["ask"].clear()\n        REPLY[0] = "Привет, сэр."\n        ask("Атлас, привет!")\n        q = LOG["ask"][-1]\n        assert q.startswith("(Respond in Russian.) (Said on the phone:") and q.endswith("Атлас, привет!"), q\n        ask("what time is it in Tokyo")\n        assert LOG["ask"][-1].startswith("(Respond in English.) (Said on the phone:"), LOG["ask"][-1]\n        until = sys.modules["ui_state"].shared_state.get("phone_active_until", 0)\n        assert until > _t.time() + 20, "компьютер молчит, пока идёт разговор с телефона"\n    finally:\n        v.get_response_language = saved\n\n\ndef _panel(path, payload=None, key=None):\n    st, _, b = call(path, "POST", json.dumps(payload or {}).encode(),\n                    {"Content-Type": "application/json", "X-Atlas-Key": key if key is not None else TOKEN})\n    return st, json.loads(b)\n\n\ndef _real_data():\n    """Настоящие notes.py и core/study.py — но на временных файлах, не на твоих данных."""\n    import importlib\n    import notes\n    d = tempfile.mkdtemp()\n    notes.DATA_FILE = os.path.join(d, "atlas_data.json")\n    study = importlib.import_module("core.study")\n    study.DB = os.path.join(d, "memory.db")\n    return notes, study\n\n\n@test\ndef todos_and_notes_screens():\n    notes, _ = _real_data()\n    assert _panel("/api/home", key="wrong")[0] == 401, "без ключа экраны закрыты"\n    st, h = _panel("/api/home")\n    assert st == 200 and h["todos"] == [] and h["notes"] == []\n    _panel("/api/todo/add", {"task": "Сдать SAT practice test"})\n    st, h = _panel("/api/todo/add", {"task": "Купить тетрадь"})\n    assert [t["task"] for t in h["todos"]] == ["Сдать SAT practice test", "Купить тетрадь"]\n    st, h = _panel("/api/todo/done", {"i": 1})\n    assert h["todos"][0]["done"] and not h["todos"][1]["done"]\n    st, h = _panel("/api/todo/delete", {"i": 2})\n    assert len(h["todos"]) == 1\n    st, h = _panel("/api/note/add", {"text": "Идея: голосовые карточки по физике"})\n    assert h["notes"] == ["Идея: голосовые карточки по физике"]\n    assert "Идея" in notes.list_notes(), "голосовая команда видит заметку с экрана"\n    st, h = _panel("/api/note/delete", {"i": 1})\n    assert h["notes"] == []\n    assert _panel("/api/todo/add", {"task": "   "})[1]["todos"] == h["todos"], "пустое дело не добавляется"\n\n\n@test\ndef study_screen_full_session():\n    _, study = _real_data()\n    study.add_cards("SAT", [{"front": "ubiquitous", "back": "вездесущий"}, {"front": "arcane", "back": "тайный"}])\n    st, h = _panel("/api/home")\n    assert h["decks"][0]["deck"] == "SAT" and h["decks"][0]["due"] == 2\n    st, r = _panel("/api/study/start", {"deck": "сат"})\n    assert st == 200 and r["card"]["front"] in ("ubiquitous", "arcane") and r["card"]["n"] == 1 and r["card"]["total"] == 2\n    first = r["card"]["front"]\n    right = {"ubiquitous": "вездесущий", "arcane": "тайный"}[first]\n    st, r = _panel("/api/study/answer", {"text": right})\n    assert r["feedback"].rstrip(".") in ("Верно", "Точно", "Так и есть", "Правильно"), r\n    assert r["card"]["n"] == 2 and "Вопрос" not in r["feedback"], "отзыв без следующего вопроса"\n    assert _panel("/api/home")[1]["study"]["n"] == 2, "открыл экран заново — тренировка продолжается"\n    st, r = _panel("/api/study/answer", {"text": ""})          # «показать ответ»\n    assert "Правильно:" in r["feedback"] and r["card"], "не знал — карточка вернётся в этой же тренировке"\n    st, r = _panel("/api/study/stop")\n    assert r["done"] and "Итог" in r["feedback"] and _panel("/api/home")[1]["study"] is None\n\n\n@test\ndef answer_by_voice_is_only_transcribed():\n    LOG["ask"].clear()\n    HEARD[0] = "вездесущий"\n    st, _, b = call("/api/transcribe", "POST", b"audio", {"Content-Type": "audio/webm", "X-Atlas-Key": TOKEN})\n    assert st == 200 and json.loads(b) == {"text": "вездесущий"} and not LOG["ask"], "мозг не вызывался"\n    assert call("/api/transcribe", "POST", b"audio", {"Content-Type": "audio/webm", "X-Atlas-Key": "nope"})[0] == 401\n    HEARD[0] = "какая погода"\n\n\n@test\ndef app_has_the_screens():\n    page = call("/")[2].decode()\n    for must in (\'id="v-todos"\', \'id="v-notes"\', \'id="v-study"\', "/api/home", "/api/study/answer", "/api/transcribe"):\n        assert must in page, must\n\n\n@test\ndef tunnel_prefers_tailscale_and_explains_what_is_missing():\n    from phone import tunnel\n    saved = (tunnel._tailscale_exe, tunnel._cloudflared_exe, tunnel._run, tunnel.subprocess.Popen)\n    try:\n        tunnel._tailscale_exe = lambda: "tailscale"\n        runs = []\n\n        def run_ok(args, timeout=20):\n            runs.append(args)\n            out = json.dumps({"BackendState": "Running", "Self": {"DNSName": "atlas-pc.tail1234.ts.net."}}) \\\n                if "status" in args else "Available within your tailnet"\n            return types.SimpleNamespace(returncode=0, stdout=out, stderr="")\n        tunnel._run = run_ok\n        assert tunnel.start(8765) == ("https://atlas-pc.tail1234.ts.net", "tailscale", "")\n        assert ["tailscale", "serve", "--bg", "8765"] in runs\n\n        def run_no_https(args, timeout=20):\n            if "status" in args:\n                return run_ok(args)\n            return types.SimpleNamespace(returncode=1, stdout="", stderr="HTTPS is not enabled for this tailnet")\n        tunnel._run = run_no_https\n        tunnel._cloudflared_exe = lambda: "cloudflared"\n\n        class FakeCF:\n            def __init__(self, args, **kw):\n                self.stdout = iter(["INF Requesting new quick Tunnel\\n",\n                                    "INF |  https://quiet-star-1234.trycloudflare.com  |\\n"])\n\n            def poll(self):\n                return None\n\n            def kill(self):\n                pass\n        tunnel.subprocess.Popen = FakeCF\n        url, kind, hint = tunnel.start(8765)\n        assert (url, kind) == ("https://quiet-star-1234.trycloudflare.com", "cloudflare"), (url, kind, hint)\n\n        tunnel._tailscale_exe = tunnel._cloudflared_exe = lambda: ""\n        url, kind, hint = tunnel.start(8765)\n        assert url is None and "Tailscale не установлен" in hint and "cloudflared не установлен" in hint\n    finally:\n        tunnel._tailscale_exe, tunnel._cloudflared_exe, tunnel._run, tunnel.subprocess.Popen = saved\n\n\n@test\ndef install_opens_a_local_qr_page_with_the_key():\n    from phone import install as I\n    import webbrowser\n    saved_open, saved_state = webbrowser.open, dict(S._state)\n    webbrowser.open = lambda url: LOG["opened"].append(url)\n    try:\n        S._state.update(url="https://atlas-pc.tail1234.ts.net", kind="tailscale")\n        msg = I.install("телефон")\n        page = LOG["opened"][-1]\n        html = open(page.replace("file:///", "/" if os.name != "nt" else ""), encoding="utf-8").read()\n        assert "QR" in msg and page.startswith("file:///"), msg\n        assert ("<img alt=\\"QR-код" in html) or (f"https://atlas-pc.tail1234.ts.net/?pair={TOKEN}" in html)\n        assert "Tailscale" in html and "iPhone" in html and "Android" in html\n        msg = I.install("телевизор")\n        assert "телевизор" in msg and f"/?pair={TOKEN}" in open(LOG["opened"][-1].replace("file:///", "/" if os.name != "nt" else ""),\n                                                               encoding="utf-8").read()\n        S._state.update(url=None, hint="Tailscale не установлен; cloudflared не установлен")\n        S.connect = lambda force=False: ""\n        msg = I.install("phone")\n        assert "Tailscale" in msg and "winget" in msg, msg\n    finally:\n        webbrowser.open = saved_open\n        S._state.clear()\n        S._state.update(saved_state)\n\n\ndef main():\n    global S, BASE, TOKEN\n    install()\n    from phone import server as S\n    S.PAIR_FILE = os.path.join(tempfile.mkdtemp(), "phone_pairing.json")\n    TOKEN = S.pairing_token(create=True)\n    port = S.start(0)\n    BASE = f"http://127.0.0.1:{port}"\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-5:]))\n    S.stop()\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n', 'phone/panels.py': '"""\nЭкраны приложения на телефоне: дела, заметки, тренировка карточек.\n\nРаботают с теми же данными, что и голос: notes.py (atlas_data.json) и core/study.py (memory.db),\nпоэтому всё, что сделано на экране, видно и Atlas на компьютере (через общую память в облаке).\n\n    POST /api/home                       → дела, заметки, колоды, серия занятий\n    POST /api/todo/add {task}            /api/todo/done {i}      /api/todo/delete {i}\n    POST /api/note/add {text}            /api/note/delete {i}\n    POST /api/study/start {deck}         /api/study/answer {text}    /api/study/stop\n    POST /api/transcribe (аудио)         → {text} — ответ на карточку голосом, без мозга\n\nНомера i — с единицы, как в голосовых командах («отметь второе дело»).\n"""\nimport threading\n\n_lock = threading.Lock()          # экран и голос не правят один файл одновременно\n\n\ndef _notes():\n    import notes\n    return notes\n\n\ndef _study():\n    from core import study\n    return study\n\n\ndef _int(data, key="i") -> int:\n    try:\n        return int(data.get(key))\n    except (TypeError, ValueError):\n        return 0\n\n\ndef home(data=None) -> dict:\n    n = _notes()._load()\n    out = {"todos": [{"task": t.get("task", ""), "done": bool(t.get("done"))} for t in n.get("todos", [])],\n           "notes": [str(x) for x in n.get("notes", [])], "decks": [], "streak": 0, "study": None}\n    try:\n        st = _study().stats()\n        out["decks"], out["streak"] = st.get("decks", []), st.get("streak", 0)\n        out["week_accuracy"] = st.get("week_accuracy")\n        out["study"] = _card_state()\n    except Exception as e:                      # карточек может не быть — экраны всё равно открываются\n        print(f"[телефон] карточки недоступны: {e}")\n    return out\n\n\ndef _text(data, key, limit=500) -> str:\n    return str((data or {}).get(key) or "").strip()[:limit]\n\n\ndef todo_add(data) -> dict:\n    task = _text(data, "task")\n    if task:\n        with _lock:\n            _notes().add_todo(task)\n    return home()\n\n\ndef todo_done(data) -> dict:\n    with _lock:\n        _notes().complete_todo(_int(data))\n    return home()\n\n\ndef todo_delete(data) -> dict:\n    with _lock:\n        _notes().delete_todo(_int(data))\n    return home()\n\n\ndef note_add(data) -> dict:\n    text = _text(data, "text", 2000)\n    if text:\n        with _lock:\n            _notes().add_note(text)\n    return home()\n\n\ndef note_delete(data) -> dict:\n    with _lock:\n        _notes().delete_note(_int(data))\n    return home()\n\n\n# ---------------------------------------------------------------------------\n# Карточки\n# ---------------------------------------------------------------------------\ndef _card_state():\n    """Текущая карточка тренировки или None."""\n    s = _study()\n    if not s.active():\n        return None\n    ses = s._session\n    card = s._card(ses["current"])\n    if not card:\n        return None\n    return {"front": card["front"], "deck": card["deck"], "n": ses["asked"] + 1,\n            "total": max(ses.get("limit") or 0, ses["asked"] + 1 + len(ses["queue"])),\n            "correct": ses["correct"]}\n\n\ndef _split(said: str, state):\n    """Ответ тренера = отзыв о прошлой карточке + вопрос следующей. Экрану нужен только отзыв."""\n    if state:\n        q = _study()._question(_study()._card(_study()._session["current"]))\n        if q and said.endswith(q):\n            return said[: -len(q)].strip()\n    return said.strip()\n\n\ndef study_start(data) -> dict:\n    said = _study().start(_text(data, "deck", 80), _int(data, "count") or 10)\n    state = _card_state()\n    return {"said": said, "feedback": "" if state else said, "card": state, "done": state is None}\n\n\ndef study_answer(data) -> dict:\n    s = _study()\n    if not s.active():\n        return {"said": "", "feedback": "Тренировка уже закончилась.", "card": None, "done": True}\n    before = s._card(s._session["current"])\n    said = s.answer(_text(data, "text"))\n    state = _card_state()\n    return {"said": said, "feedback": _split(said, state), "card": state, "done": state is None,\n            "answer": before["back"] if before else ""}\n\n\ndef study_stop(data=None) -> dict:\n    said = _study().stop()\n    return {"said": said, "feedback": said, "card": None, "done": True}\n\n\nROUTES = {\n    "/api/home": home,\n    "/api/todo/add": todo_add, "/api/todo/done": todo_done, "/api/todo/delete": todo_delete,\n    "/api/note/add": note_add, "/api/note/delete": note_delete,\n    "/api/study/start": study_start, "/api/study/answer": study_answer, "/api/study/stop": study_stop,\n}\n'}


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in ORIG:
        shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    if os.path.exists(p("phone/panels.py")):
        os.remove(p("phone/panels.py"))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_phoneui_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p("phone/panels.py")):
    sys.exit("Уже установлено. Проверка: python tests/test_phone.py")

differ = []
for rel, h in ORIG.items():
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime("backup_phoneui_%Y%m%d_%H%M%S"))
for rel in ORIG:
    os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
    shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, s in NEW.items():
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)
print("  ✓ приложение: вкладки Atlas, Дела, Заметки, Учёба; быстрые кнопки")
print("  ✓ сервер: phone/panels.py — данные для вкладок (с тем же ключом сопряжения)")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновит облако сам.")
